-- grid_comparators
SELECT replace(series, 'EIA_', '') AS region, baseline, mae_improvement_pct AS improvement, pairs, pair_coverage AS coverage, baseline_mae, candidate_mae, p95_regression_pct AS tail_regression, status FROM stage8_metrics WHERE family='grid' AND scenario='clean' AND horizon_steps=3 AND candidate='median5' AND slice='all' ORDER BY series, baseline;

-- marine_availability
WITH selected AS (SELECT replace(series,'NDBC_','') AS station, scheduled_count AS scheduled, truth_count AS observed, pairs, pair_coverage FROM stage8_metrics WHERE family='marine' AND scenario='clean' AND horizon_steps=1 AND candidate='median5' AND baseline='persistence' AND slice='all') SELECT station, 'Observed targets / scheduled' AS measure, 1.0*observed/scheduled AS fraction, scheduled, observed, pairs FROM selected UNION ALL SELECT station, 'Paired / observed targets' AS measure, pair_coverage AS fraction, scheduled, observed, pairs FROM selected ORDER BY station, measure;

-- scenario_decisions
WITH selected AS (SELECT * FROM stage8_metrics WHERE scenario IN ('clean','spike_positive','missing10_s17','missing30_s17','delay3','outage') AND slice='all' AND baseline='persistence'), statuses(status,decision) AS (VALUES ('DESCRIPTIVE_CANDIDATE_ONLY','Candidate only'), ('HOLD_INSUFFICIENT_SUPPORT','Insufficient support'), ('HOLD_THRESHOLD_OR_STABILITY','Threshold/stability hold'), ('REJECT_MAE_REGRESSION','MAE regression')), scenarios AS (SELECT DISTINCT scenario FROM selected) SELECT replace(replace(scenario,'_s17',''),'_',' ') AS scenario, decision, (SELECT count(*) FROM selected s WHERE s.scenario=scenarios.scenario AND s.status=statuses.status) AS count, (SELECT count(*) FROM selected s WHERE s.scenario=scenarios.scenario) AS total, 'persistence' AS baseline, '17 series × 3 horizons × 3 candidates; dependent cells' AS scope FROM scenarios CROSS JOIN statuses ORDER BY scenario,decision;
